21	Connection::Connection(DatabaseInstance &database)
22	    : context(make_shared_ptr<ClientContext>(database.shared_from_this())), warning_cb(nullptr) {
23		ConnectionManager::Get(database).AddConnection(*context);
24	#ifdef DEBUG
25		EnableProfiling();
26		context->config.emit_profiler_output = false;
27	#endif
28	}
