56	optional_ptr<ProfilingNode> Connection::GetProfilingTree() {
57		auto &client_config = ClientConfig::GetConfig(*context);
58		auto enable_profiler = client_config.enable_profiler;
59	
60		if (!enable_profiler) {
61			throw Exception(ExceptionType::SETTINGS, "Profiling is not enabled for this connection");
62		}
63		auto &profiler = QueryProfiler::Get(*context);
64		return profiler.GetRoot();
65	}
