180	void Connection::Append(TableDescription &description, DataChunk &chunk) {
181		if (chunk.size() == 0) {
182			return;
183		}
184		ColumnDataCollection collection(Allocator::Get(*context), chunk.GetTypes());
185		collection.Append(chunk);
186		Append(description, collection);
187	}
