88	unique_ptr<PendingQueryResult> PreparedStatement::PendingQuery(vector<Value> &values, bool allow_stream_result) {
89		case_insensitive_map_t<BoundParameterData> named_values;
90		for (idx_t i = 0; i < values.size(); i++) {
91			auto &val = values[i];
92			named_values[std::to_string(i + 1)] = BoundParameterData(val);
93		}
94		return PendingQuery(named_values, allow_stream_result);
