95		template <class PAYLOAD>
96		static string ExcessValuesException(const case_insensitive_map_t<idx_t> &parameters,
97		                                    case_insensitive_map_t<PAYLOAD> &values) {
98			// Too many values
99			set<string> excess_set;
100			for (auto &pair : values) {
101				auto &name = pair.first;
102				if (!parameters.count(name)) {
103					excess_set.insert(name);
104				}
105			}
106			vector<string> excess_values;
107			for (auto &val : excess_set) {
108				excess_values.push_back(val);
109			}
110			return StringUtil::Format("Parameter argument/count mismatch, identifiers of the excess parameters: %s",
111			                          StringUtil::Join(excess_values, ", "));
112		}
