133		template <class PAYLOAD>
134		static void VerifyParameters(case_insensitive_map_t<PAYLOAD> &provided,
135		                             const case_insensitive_map_t<idx_t> &expected) {
136			if (expected.size() == provided.size()) {
137				// Same amount of identifiers, if
138				for (auto &pair : expected) {
139					auto &identifier = pair.first;
140					if (!provided.count(identifier)) {
141						throw InvalidInputException(MissingValuesException(expected, provided));
142					}
143				}
144				return;
145			}
146			// Mismatch in expected and provided parameters/values
147			if (expected.size() > provided.size()) {
148				throw InvalidInputException(MissingValuesException(expected, provided));
149			} else {
150				D_ASSERT(provided.size() > expected.size());
151				throw InvalidInputException(ExcessValuesException(expected, provided));
152			}
153		}
