110	static void parallel_pending_query(Connection *conn, bool *correct, size_t threadnr) {
111		correct[threadnr] = true;
112		for (size_t i = 0; i < 100; i++) {
113			// run pending query and then execute it
114			auto executor = conn->PendingQuery("SELECT * FROM integers ORDER BY i");
115			try {
116				// this will randomly throw an exception if another thread calls pending query first
117				auto result = executor->Execute();
118				if (!CHECK_COLUMN(result, 0, {1, 2, 3, Value()})) {
119					correct[threadnr] = false;
120				}
121			} catch (...) {
122				continue;
123			}
124		}
125	}
