46		//! Returns the result of the query as an actual query result.
47		//! This returns (mostly) instantly if ExecuteTask has been called until RESULT_READY was returned.
48		DUCKDB_API unique_ptr<QueryResult> Execute();
49	
50		DUCKDB_API void Close();
51	
52		//! Function to determine whether execution is considered finished
