26	bool CheckCatalogIdentity(ClientContext &context, const string &catalog_name,
27	                          const StatementProperties::CatalogIdentity catalog_identity) {
28		// some catalogs don't support catalog version, we can't check identity in that case
29		if (!catalog_identity.catalog_version.IsValid()) {
30			return false;
31		}
32		auto database = DatabaseManager::Get(context).GetDatabase(context, catalog_name);
33		if (!database) {
34			throw BinderException("Prepared statement requires database %s but it was not attached", catalog_name);
35		}
36		Transaction::Get(context, *database);
37		auto current_catalog_oid = database->GetCatalog().GetOid();
38		auto current_catalog_version = database->GetCatalog().GetCatalogVersion(context);
39	
40		return StatementProperties::CatalogIdentity {current_catalog_oid, current_catalog_version} == catalog_identity;
41	}
