105	bool PreparedStatementData::TryGetType(const string &identifier, LogicalType &result) {
106		auto it = value_map.find(identifier);
107		if (it == value_map.end()) {
108			return false;
109		}
110		if (it->second->return_type.id() != LogicalTypeId::INVALID) {
111			result = it->second->return_type;
112		} else {
113			result = it->second->GetValue().type();
114		}
115		return true;
116	}
