118	LogicalType PreparedStatementData::GetType(const string &identifier) {
119		LogicalType result;
120		if (!TryGetType(identifier, result)) {
121			throw BinderException("Could not find parameter identified with: %s", identifier);
122		}
123		return result;
124	}
